"""Routing computations over an explicit topology/availability state.

Two protocols live here:

* link-state shortest-path forwarding tables (Dijkstra) used by ``compute``
  and every replay snapshot;
* synchronous distance-vector rounds used by ``converge``.

Both are pure functions of the supplied adjacency map and ordered node
tuple.  Neighbors are always iterated in sorted name order and equal-metric
choices use a strict comparison, so ties deterministically select the
smaller next-hop name regardless of dict insertion order or hash seed.
"""
import heapq


def forwarding_table(source, ordered_nodes, adjacency):
    """Dijkstra from ``source``; ties on total metric pick the smaller hop."""
    distances = {source: 0}
    next_hops = {}
    # Label is (total metric, first hop name); "" is a sentinel for the source
    # and sorts before any real (necessarily non-empty) node name.
    heap = [(0, "", source)]
    settled = set()
    while heap:
        distance, first_hop, node = heapq.heappop(heap)
        if node in settled:
            continue
        settled.add(node)
        distances[node] = distance
        next_hops[node] = first_hop
        for neighbor in sorted(adjacency[node]):
            if neighbor in settled:
                continue
            metric = adjacency[node][neighbor]
            candidate = distance + metric
            candidate_hop = neighbor if node == source else first_hop
            heapq.heappush(heap, (candidate, candidate_hop, neighbor))

    table = {}
    for destination in ordered_nodes:
        if destination == source:
            table[destination] = {"nextHop": None, "metric": 0}
        elif destination in distances:
            table[destination] = {
                "nextHop": next_hops[destination],
                "metric": distances[destination],
            }
        else:
            table[destination] = {"nextHop": None, "metric": None}
    return table


def link_state_snapshot(ordered_nodes, active_adjacency, down_nodes):
    """Forwarding tables for every node from an availability state.

    Up routers are computed against the subgraph of usable links; a down
    router's whole row is ``null``/``null``.  Destinations that are down or
    unreachable likewise come out ``null``/``null`` from Dijkstra.
    """
    routers = {}
    for source in ordered_nodes:
        if source in down_nodes:
            routers[source] = {
                destination: {"nextHop": None, "metric": None}
                for destination in ordered_nodes
            }
        else:
            routers[source] = forwarding_table(
                source, ordered_nodes, active_adjacency
            )
    return routers


def initial_distance_vectors(ordered_nodes, adjacency):
    """Round 0: each router knows only itself and its directly connected links."""
    vectors = {}
    for router in ordered_nodes:
        table = {}
        for destination in ordered_nodes:
            if destination == router:
                table[destination] = {"nextHop": None, "metric": 0}
            elif destination in adjacency[router]:
                table[destination] = {
                    "nextHop": destination,
                    "metric": adjacency[router][destination],
                }
            else:
                table[destination] = {"nextHop": None, "metric": None}
        vectors[router] = table
    return vectors


def distance_vector_round(previous, ordered_nodes, adjacency):
    """Synchronously update every router from the previous round's ads."""
    current = {}
    for router in ordered_nodes:
        table = {}
        for destination in ordered_nodes:
            if destination == router:
                table[destination] = {"nextHop": None, "metric": 0}
                continue
            best_metric = None
            best_hop = None
            for neighbor in sorted(adjacency[router]):
                advertised = previous[neighbor][destination]
                if advertised["metric"] is None:
                    continue
                candidate = adjacency[router][neighbor] + advertised["metric"]
                # Neighbors are iterated in name order, so the first best
                # candidate keeps the smaller next-hop name on ties.
                if best_metric is None or candidate < best_metric:
                    best_metric = candidate
                    best_hop = neighbor
            if best_metric is None:
                table[destination] = {"nextHop": None, "metric": None}
            else:
                table[destination] = {"nextHop": best_hop, "metric": best_metric}
        current[router] = table
    return current


def distance_vector_convergence(ordered_nodes, adjacency):
    """Return every changed synchronous round from round 0 to a fixed point."""
    vectors = initial_distance_vectors(ordered_nodes, adjacency)
    rounds = [{"round": 0, "routers": vectors}]
    while True:
        updated = distance_vector_round(vectors, ordered_nodes, adjacency)
        if updated == vectors:
            break
        vectors = updated
        rounds.append({"round": len(rounds), "routers": vectors})
    return rounds


def _unreachable_row(ordered_nodes):
    """A fresh row advertising every destination (including self) as down."""
    return {
        destination: {"nextHop": None, "metric": None}
        for destination in ordered_nodes
    }


def distance_vector_failure_round_zero(
    previous, ordered_nodes, active_adjacency, down_nodes
):
    """Round 0 immediately after a failure/recovery event.

    Every online router keeps the routes it advertised in the previous
    converged state, except:

    * a route whose next hop is no longer an available direct neighbor (the
      failed or disconnected neighbor) becomes unreachable;
    * a currently available direct neighbor always advertises the direct
      route again, so a recovered link is usable at once;
    * a down router's whole row is unreachable.

    A recovering router is handed a prior row of its own that is entirely
    unreachable, which leaves it knowing only itself and its currently
    available direct neighbors.
    """
    vectors = {}
    for router in ordered_nodes:
        if router in down_nodes:
            vectors[router] = _unreachable_row(ordered_nodes)
            continue
        table = {}
        prior = previous[router]
        for destination in ordered_nodes:
            if destination == router:
                table[destination] = {"nextHop": None, "metric": 0}
            elif destination in active_adjacency[router]:
                table[destination] = {
                    "nextHop": destination,
                    "metric": active_adjacency[router][destination],
                }
            else:
                entry = prior[destination]
                hop = entry["nextHop"]
                if hop is None or hop not in active_adjacency[router]:
                    table[destination] = {"nextHop": None, "metric": None}
                else:
                    # A copy, so retained advertisements never alias caller
                    # data or later rounds.
                    table[destination] = dict(entry)
        vectors[router] = table
    return vectors


def distance_vector_round_infinity(
    previous, ordered_nodes, adjacency, down_nodes, infinity_metric
):
    """Synchronously update from prior ads with an infinity threshold.

    Same scan/tie rules as :func:`distance_vector_round`, with no split
    horizon or poison reverse: every available neighbor's previous-round
    advertisement is read.  A candidate metric at or above
    ``infinity_metric`` counts as unreachable.  Down routers keep an
    entirely unreachable row.
    """
    current = {}
    for router in ordered_nodes:
        if router in down_nodes:
            current[router] = _unreachable_row(ordered_nodes)
            continue
        table = {}
        for destination in ordered_nodes:
            if destination == router:
                table[destination] = {"nextHop": None, "metric": 0}
                continue
            best_metric = None
            best_hop = None
            for neighbor in sorted(adjacency[router]):
                advertised = previous[neighbor][destination]
                if advertised["metric"] is None:
                    continue
                candidate = adjacency[router][neighbor] + advertised["metric"]
                if candidate >= infinity_metric:
                    continue
                # Neighbors are iterated in name order, so the first best
                # candidate keeps the smaller next-hop name on ties.
                if best_metric is None or candidate < best_metric:
                    best_metric = candidate
                    best_hop = neighbor
            if best_metric is None:
                table[destination] = {"nextHop": None, "metric": None}
            else:
                table[destination] = {"nextHop": best_hop, "metric": best_metric}
        current[router] = table
    return current


def distance_vector_failure_convergence(
    round_zero, ordered_nodes, active_adjacency, down_nodes, infinity_metric
):
    """Record round 0 and every later changed round up to a fixed point.

    After a cost increase a stale route's metric rises by at least the link
    cost along its dependency cycle until it reaches the threshold and is
    flushed as unreachable (the count-to-infinity process), so the scan
    always terminates; a surviving finite alternative wins earlier.
    """
    rounds = [{"round": 0, "routers": round_zero}]
    vectors = round_zero
    while True:
        updated = distance_vector_round_infinity(
            vectors,
            ordered_nodes,
            active_adjacency,
            down_nodes,
            infinity_metric,
        )
        if updated == vectors:
            break
        vectors = updated
        rounds.append({"round": len(rounds), "routers": vectors})
    return rounds


# ---------------------------------------------------------------------------
# Route hold-down (optional replay-dv suppression)
# ---------------------------------------------------------------------------
#
# A hold-down keeps a destination unreachable for a finite number of full
# synchronous update rounds after the router's own finite route to it was
# invalidated, so a possibly unstable alternative cannot be adopted at once.
# The suppression state is a ``{router: {destination: remaining_rounds}}``
# map carried *beside* the advertised vectors (never inside them): a held
# route still advertises exactly ``null``/``null``, so the event format, the
# infinity threshold, synchronous updates and tie breaks are all unchanged.
#
# An internal timer holds a *positive* remaining count while it is live:
#
# * Round 0 (immediately after an event) starts every invalidated route's
#   timer at ``hold_down`` and publishes that count.  Invalidation is found
#   as a monotone closure: a retained finite route whose selected next hop is
#   gone, is down, or itself advertises the destination unreachable at round 0
#   is itself invalidated -- and that conclusion propagates transitively.
# * Each later synchronous round suppresses while the carried count is
#   positive, then hands the next round one less.  A route invalidated later
#   (its selected hop's advertisement turns unusable) starts a fresh window at
#   that round.  More unreachability arriving inside a live window simply
#   keeps counting down; it never extends the window.
# * A destination that is a current direct neighbor is always adopted at its
#   direct metric, at any round, and its timer is cleared immediately.
# * Once the count reaches zero the *next* round rejoins ordinary selection.
#
# Down routers hold no timers; their whole row stays ``null``/``null``.


def _empty_holddowns(ordered_nodes):
    """A fresh ``{router: {destination: remaining}}`` map, one row per router."""
    return {router: {} for router in ordered_nodes}


def holddowns_public(holddowns, ordered_nodes):
    """A fresh sorted copy of the suppression map for published output."""
    return {
        router: {
            destination: holddowns[router][destination]
            for destination in sorted(holddowns[router])
        }
        for router in ordered_nodes
    }


def _holddown_round_zero_vectors(
    previous, ordered_nodes, active_adjacency, down_nodes
):
    """Round-zero forwarding vectors under hold-down.

    These agree with :func:`distance_vector_failure_round_zero` and then
    transitively null any retained finite route whose selected next hop now
    advertises the destination as unreachable.  Direct neighbors, self routes
    and down-router rows are exactly as in the legacy round zero.  The map is
    monotone (finite routes only become null), so iteration reaches a unique
    least fixed point independent of scan order.
    """
    current = distance_vector_failure_round_zero(
        previous, ordered_nodes, active_adjacency, down_nodes
    )
    while True:
        updated = {}
        for router in ordered_nodes:
            if router in down_nodes:
                updated[router] = _unreachable_row(ordered_nodes)
                continue
            row = {}
            for destination in ordered_nodes:
                if destination == router:
                    row[destination] = {"nextHop": None, "metric": 0}
                elif destination in active_adjacency[router]:
                    row[destination] = {
                        "nextHop": destination,
                        "metric": active_adjacency[router][destination],
                    }
                else:
                    entry = current[router][destination]
                    hop = entry["nextHop"]
                    if hop is None or hop not in active_adjacency[router]:
                        row[destination] = {"nextHop": None, "metric": None}
                    elif current[hop][destination]["metric"] is None:
                        # The still-present selected hop no longer offers a
                        # way to the destination: null it, possibly enabling
                        # further nulls on the next closure pass.
                        row[destination] = {"nextHop": None, "metric": None}
                    else:
                        row[destination] = dict(entry)
            updated[router] = row
        if updated == current:
            return current
        current = updated


def distance_vector_holddown_round_zero(
    previous, ordered_nodes, active_adjacency, down_nodes, hold_down
):
    """Round 0 after an event with hold-down enabled.

    Returns ``(vectors, holddowns)`` where every online router's previously
    finite, non-direct route that round zero renders unreachable starts a
    ``hold_down``-round timer; everything else carries no timer.
    """
    vectors = _holddown_round_zero_vectors(
        previous, ordered_nodes, active_adjacency, down_nodes
    )
    holddowns = _empty_holddowns(ordered_nodes)
    if hold_down <= 0:
        return vectors, holddowns
    for router in ordered_nodes:
        if router in down_nodes:
            continue
        timed = holddowns[router]
        for destination in ordered_nodes:
            if destination == router or destination in active_adjacency[router]:
                continue
            prior = previous[router][destination]
            if (
                prior["nextHop"] is not None
                and vectors[router][destination]["metric"] is None
            ):
                timed[destination] = hold_down
    return vectors, holddowns


def _selected_hop_usable(
    router, destination, hop, previous, adjacency, infinity_metric
):
    """Whether the route currently selected via ``hop`` stays finite.

    The same usability test an ordinary synchronous round applies to that
    hop's own previous-round advertisement: a present neighbor advertising
    unreachable, or a total metric at/above the infinity threshold, no longer
    carries the route.
    """
    if hop not in adjacency[router]:
        return False
    advertised = previous[hop][destination]["metric"]
    if advertised is None:
        return False
    return adjacency[router][hop] + advertised < infinity_metric


def distance_vector_holddown_round(
    previous,
    ordered_nodes,
    adjacency,
    down_nodes,
    infinity_metric,
    holddowns,
    hold_down,
):
    """One synchronous round with hold-down suppression.

    Returns ``(vectors, holddowns)`` for the *next* round.  For an online
    router and a destination that is not a current direct neighbor:

    * a live timer (positive carried count) forces ``null``/``null`` and
      refuses every learned finite advertisement this round; the next round
      receives one less, and the timer disappears at zero -- repeated
      unreachability never resets it;
    * a selected finite route whose hop has just become unusable starts a
      fresh window and is reported unreachable this round;
    * otherwise the ordinary synchronous best-neighbor scan runs, with the
      infinity threshold and smaller-next-hop tie rule unchanged.

    A destination that is currently directly reachable is always adopted at
    its direct metric and clears any timer at once.
    """
    current = {}
    next_holddowns = _empty_holddowns(ordered_nodes)
    for router in ordered_nodes:
        if router in down_nodes:
            current[router] = _unreachable_row(ordered_nodes)
            continue
        row = {}
        for destination in ordered_nodes:
            if destination == router:
                row[destination] = {"nextHop": None, "metric": 0}
                continue
            if destination in adjacency[router]:
                # Direct reachability overrides any live hold-down and clears
                # its timer.
                row[destination] = {
                    "nextHop": destination,
                    "metric": adjacency[router][destination],
                }
                continue

            remaining = holddowns[router].get(destination)
            selected_hop = previous[router][destination]["nextHop"]
            invalidated = (
                remaining is None
                and selected_hop is not None
                and not _selected_hop_usable(
                    router,
                    destination,
                    selected_hop,
                    previous,
                    adjacency,
                    infinity_metric,
                )
            )

            if invalidated:
                # The finite route in use failed this round; the window opens.
                row[destination] = {"nextHop": None, "metric": None}
                next_holddowns[router][destination] = hold_down
                continue

            if remaining is not None:
                # Inside the suppression window: no learned finite route may
                # restore the destination; count the consumed round down.
                row[destination] = {"nextHop": None, "metric": None}
                if remaining - 1 > 0:
                    next_holddowns[router][destination] = remaining - 1
                continue

            # No window: ordinary synchronous best-route selection.
            best_metric = None
            best_hop = None
            for neighbor in sorted(adjacency[router]):
                advertised = previous[neighbor][destination]["metric"]
                if advertised is None:
                    continue
                candidate = adjacency[router][neighbor] + advertised
                if candidate >= infinity_metric:
                    continue
                # Neighbors are iterated in name order, so the first best
                # candidate keeps the smaller next-hop name on ties.
                if best_metric is None or candidate < best_metric:
                    best_metric = candidate
                    best_hop = neighbor
            if best_metric is None:
                row[destination] = {"nextHop": None, "metric": None}
            else:
                row[destination] = {
                    "nextHop": best_hop, "metric": best_metric
                }
        current[router] = row
    return current, next_holddowns


def distance_vector_holddown_convergence(
    round_zero,
    holddowns_zero,
    ordered_nodes,
    active_adjacency,
    down_nodes,
    infinity_metric,
    hold_down,
):
    """Record rounds under hold-down until vectors and timers are both stable.

    Round 0 is recorded as given; each later round is one synchronous
    hold-down update.  A round is recorded while either the forwarding
    vectors or the published hold-down map still change, so
    ``convergenceRound`` points at the last round that is not yet a fixed
    point under both.  Returns ``(rounds, final_vectors)``.
    """
    rounds = [
        {
            "round": 0,
            "routers": round_zero,
            "holdDowns": holddowns_public(holddowns_zero, ordered_nodes),
        }
    ]
    vectors = round_zero
    holddowns = holddowns_zero
    while True:
        updated, next_holddowns = distance_vector_holddown_round(
            vectors,
            ordered_nodes,
            active_adjacency,
            down_nodes,
            infinity_metric,
            holddowns,
            hold_down,
        )
        next_public = holddowns_public(next_holddowns, ordered_nodes)
        if (
            updated == vectors
            and next_public == rounds[-1]["holdDowns"]
        ):
            break
        vectors = updated
        holddowns = next_holddowns
        rounds.append(
            {
                "round": len(rounds),
                "routers": vectors,
                "holdDowns": next_public,
            }
        )
    return rounds, vectors

"""Topology validation and the validated, immutable topology object.

A :class:`Topology` is produced solely by :func:`validate_topology` from a
decoded JSON value.  It stores nodes in stable name order and links keyed by
their canonical undirected endpoint pair, so every later computation is
independent of declaration order and of any dict iteration order.
"""
from dataclasses import dataclass

from .errors import InvalidTopology


@dataclass(frozen=True)
class Topology:
    """A validated undirected weighted topology.

    ``nodes`` is sorted by name; ``links`` maps canonical pair
    ``(smaller, larger)`` to its positive integer metric.  Both fields use
    only immutable types.
    """

    nodes: tuple
    links: frozenset

    @property
    def node_set(self):
        return set(self.nodes)

    @property
    def link_pairs(self):
        return frozenset(pair for pair, _metric in self.links)

    def adjacency(self):
        """Return a fresh ``{node: {neighbor: metric}}`` undirected map."""
        adjacency = {node: {} for node in self.nodes}
        for (source, target), metric in self.links:
            adjacency[source][target] = metric
            adjacency[target][source] = metric
        return adjacency


def _is_positive_int(value):
    # bool is a subclass of int; JSON true/false must not count as a metric.
    return isinstance(value, int) and not isinstance(value, bool) and value > 0


def canonical_pair(source, target):
    """Order-independent key for an undirected link endpoint pair."""
    return (source, target) if source < target else (target, source)


def validate_topology(topology):
    """Validate a decoded topology value; return an immutable :class:`Topology`.

    Raises :class:`InvalidTopology` for any malformed structure, value,
    unknown endpoint reference, self-loop, non-positive/non-integer metric
    or duplicate undirected link.
    """
    if not isinstance(topology, dict):
        raise InvalidTopology("topology must be an object")
    nodes_raw = topology.get("nodes")
    links_raw = topology.get("links")
    if not isinstance(nodes_raw, list) or not isinstance(links_raw, list):
        raise InvalidTopology("nodes and links must be arrays")

    nodes = []
    declared = set()
    for node in nodes_raw:
        if not isinstance(node, str) or node == "" or node in declared:
            raise InvalidTopology("illegal node declaration")
        declared.add(node)
        nodes.append(node)

    links = set()
    seen_pairs = set()
    for link in links_raw:
        if not isinstance(link, dict):
            raise InvalidTopology("link must be an object")
        if "from" not in link or "to" not in link or "metric" not in link:
            raise InvalidTopology("link requires from, to and metric")
        source, target, metric = link["from"], link["to"], link["metric"]
        if not isinstance(source, str) or not isinstance(target, str):
            raise InvalidTopology("link endpoints must be strings")
        if source not in declared or target not in declared:
            raise InvalidTopology("link references an undeclared node")
        if source == target:
            raise InvalidTopology("self-loops are not allowed")
        if not _is_positive_int(metric):
            raise InvalidTopology("metric must be a positive integer")
        pair = canonical_pair(source, target)
        if pair in seen_pairs:
            raise InvalidTopology("duplicate undirected link")
        seen_pairs.add(pair)
        links.add((pair, metric))

    return Topology(nodes=tuple(sorted(nodes)), links=frozenset(links))

"""Command line entry point: version, compute, converge, replay, replay-dv,
replay-ls and help.

This layer contains only argument checking, file reading, JSON parsing and
JSON serialization.  All topology validation, protocol computation and
failure-state progression live in the I/O-free
:mod:`packet_routing_sim.core` package.
"""
import json
import sys

from . import __version__
from .core import (
    InvalidScenario,
    InvalidTopology,
    compute_topology,
    converge_topology,
    replay_dv_validated,
    replay_ls_validated,
    replay_validated,
    validate_topology,
)

COMPUTE_USAGE = "usage: python3 -m packet_routing_sim compute TOPOLOGY.json"
CONVERGE_USAGE = "usage: python3 -m packet_routing_sim converge TOPOLOGY.json"
REPLAY_USAGE = (
    "usage: python3 -m packet_routing_sim replay TOPOLOGY.json SCENARIO.json"
)
REPLAY_DV_USAGE = (
    "usage: python3 -m packet_routing_sim replay-dv TOPOLOGY.json SCENARIO.json"
)
REPLAY_LS_USAGE = (
    "usage: python3 -m packet_routing_sim replay-ls TOPOLOGY.json SCENARIO.json"
)

USAGE = """usage: python3 -m packet_routing_sim <command>

commands:
  version                       print the package version
  compute TOPOLOGY.json         compute shortest-path forwarding tables
                                from a static undirected topology
  converge TOPOLOGY.json        show distance-vector convergence round
                                by round from a static undirected topology
  replay TOPOLOGY.json SCENARIO.json
                                replay the static link-state
                                failure timeline
  replay-dv TOPOLOGY.json SCENARIO.json
                                show distance-vector failure
                                convergence round by round
  replay-ls TOPOLOGY.json SCENARIO.json
                                show link-state flooding round by round
  help                          print this message
"""


# Sentinel for "reading/parsing failed and the error was already reported";
# an integer would collide with a JSON document that legitimately decodes to
# one (e.g. 42).
_READ_FAILED = object()


def _read_json(path, unreadable_message, invalid_message):
    """Read and decode ``path``.

    Report ``unreadable_message`` (with the path) when the file cannot be
    read and ``invalid_message`` when it is not valid JSON.  Return the
    decoded value, or ``_READ_FAILED`` after reporting.
    """
    try:
        with open(path, "rb") as stream:
            raw = stream.read()
    except OSError:
        print(unreadable_message.format(path=path), file=sys.stderr)
        return _READ_FAILED
    try:
        return json.loads(raw)
    except ValueError:
        print(invalid_message, file=sys.stderr)
        return _READ_FAILED


def _emit(result):
    """Serialize a core result in the published wire format."""
    sys.stdout.write(json.dumps(result, indent=2, ensure_ascii=False) + "\n")


def run_compute(path):
    topology = _read_json(
        path,
        "cannot read topology: {path}",
        "invalid topology",
    )
    if topology is _READ_FAILED:
        return 2
    try:
        result = compute_topology(topology)
    except InvalidTopology:
        print("invalid topology", file=sys.stderr)
        return 2
    _emit(result)
    return 0


def run_converge(path):
    topology = _read_json(
        path,
        "cannot read topology: {path}",
        "invalid topology",
    )
    if topology is _READ_FAILED:
        return 2
    try:
        result = converge_topology(topology)
    except InvalidTopology:
        print("invalid topology", file=sys.stderr)
        return 2
    _emit(result)
    return 0


def _run_replay(topology_path, scenario_path, replay_validated):
    """Shared file/error/serialization boundary for every replay command.

    Topology problems are always reported before the scenario is even read
    or validated.  Structural scenario failures and illegal state
    transitions share the one ``invalid scenario`` report.
    """
    topology = _read_json(
        topology_path,
        "cannot read topology: {path}",
        "invalid topology",
    )
    if topology is _READ_FAILED:
        return 2
    try:
        topo = validate_topology(topology)
    except InvalidTopology:
        print("invalid topology", file=sys.stderr)
        return 2

    scenario = _read_json(
        scenario_path,
        "cannot read scenario: {path}",
        "invalid scenario",
    )
    if scenario is _READ_FAILED:
        return 2
    try:
        result = replay_validated(topo, scenario)
    except InvalidScenario:
        print("invalid scenario", file=sys.stderr)
        return 2
    _emit(result)
    return 0


def run_replay(topology_path, scenario_path):
    return _run_replay(topology_path, scenario_path, replay_validated)


def run_replay_dv(topology_path, scenario_path):
    return _run_replay(topology_path, scenario_path, replay_dv_validated)


def run_replay_ls(topology_path, scenario_path):
    return _run_replay(topology_path, scenario_path, replay_ls_validated)


def main(argv: list[str] | None = None) -> int:
    args = list(sys.argv[1:] if argv is None else argv)
    command = args[0] if args else "help"
    if command == "version":
        print(__version__)
        return 0
    if command == "compute":
        if len(args) != 2:
            print(COMPUTE_USAGE, file=sys.stderr)
            return 2
        return run_compute(args[1])
    if command == "converge":
        if len(args) != 2:
            print(CONVERGE_USAGE, file=sys.stderr)
            return 2
        return run_converge(args[1])
    if command == "replay":
        if len(args) != 3:
            print(REPLAY_USAGE, file=sys.stderr)
            return 2
        return run_replay(args[1], args[2])
    if command == "replay-dv":
        if len(args) != 3:
            print(REPLAY_DV_USAGE, file=sys.stderr)
            return 2
        return run_replay_dv(args[1], args[2])
    if command == "replay-ls":
        if len(args) != 3:
            print(REPLAY_LS_USAGE, file=sys.stderr)
            return 2
        return run_replay_ls(args[1], args[2])
    if command in {"help", "-h", "--help"}:
        print(USAGE, end="")
        return 0
    print(f"unknown command: {command}", file=sys.stderr)
    print(USAGE, end="", file=sys.stderr)
    return 2


if __name__ == "__main__":
    raise SystemExit(main())

"""Link-state neighbor discovery, LSA flooding and per-database SPF.

This module models the link-state replay as deterministic synchronous rounds
over an explicit availability state (which nodes and links are up, supplied
by :mod:`packet_routing_sim.core.state`).  It performs no I/O of any kind and
depends on no dict insertion order: nodes and neighbors are always scanned in
sorted name order.

An LSA is ``{"sequence": <int>, "neighbors": [<sorted names>]}`` and a link-
state database maps an originator name to the newest LSA held for it.  An
incoming LSA is accepted only when its sequence number is strictly greater
than the one already held for the same originator.  The link metric is the
single undirected topology metric, hence identical from both endpoints; a
link participates in SPF only while both endpoints' newest held LSAs still
declare each other.

Round model
-----------

* Round 0 is built explicitly.  At the fault-free start every online router
  discovers its available direct neighbors, originates a sequence-1 LSA with
  those neighbors sorted by name, and installs only its own LSA into its own
  database.  After an event the converged databases are inherited; online
  endpoints whose adjacency changed bump their local sequence (a recovered
  node continues from its own historical sequence) and install the new LSA,
  everyone else keeps the old view, and a recovered node otherwise starts
  with an empty database.  Down routers originate nothing and hold no
  database.
* Each later round every online router synchronously relays the newest LSAs
  it held at the start of the round over each currently available link; a
  receiver accepts only a strictly higher-sequence LSA from the same
  originator.  Rounds are recorded while any database changes, stopping at a
  fixed point.

Every online router independently runs Dijkstra over its own current
database view, so a router that has not yet learned a newer LSA can briefly
keep an old route.  Equal-cost paths keep the smaller next-hop name.
"""
from .routing import forwarding_table


def make_lsa(sequence, neighbors):
    """Build one JSON-shaped local LSA with sorted neighbor names."""
    return {"sequence": sequence, "neighbors": sorted(neighbors)}


def copy_lsa(lsa):
    """Fresh copy of an LSA whose neighbor list shares nothing with the source."""
    return {"sequence": lsa["sequence"], "neighbors": list(lsa["neighbors"])}


def active_neighbor_sets(ordered_nodes, active_adjacency):
    """``{node: frozenset(its currently available neighbors)}``."""
    return {
        node: frozenset(active_adjacency[node]) for node in ordered_nodes
    }


def changed_endpoints(
    ordered_nodes, old_neighbors, new_neighbors, down_nodes, recovered=frozenset()
):
    """Online nodes whose discovered adjacency changed across an event.

    This is every currently online node with a different available-neighbor
    set, plus every node that just recovered (even one with no live
    neighbors, so it still originates an LSA continuing its own historical
    sequence).  A node that went down is excluded: it originates nothing.
    """
    changed = {node for node in recovered if node not in down_nodes}
    for node in ordered_nodes:
        if node in down_nodes:
            continue
        if old_neighbors.get(node, frozenset()) != new_neighbors[node]:
            changed.add(node)
    return changed


def baseline_databases(ordered_nodes, new_neighbors):
    """Fault-free round zero and the initial per-node sequence history.

    Every node originates a sequence-1 LSA and installs only its own LSA.
    """
    databases = {}
    sequences = {}
    for node in ordered_nodes:
        databases[node] = {node: make_lsa(1, new_neighbors[node])}
        sequences[node] = 1
    return databases, sequences


def event_databases(
    previous, ordered_nodes, new_neighbors, down_nodes, changed, sequences
):
    """Round-zero databases immediately after one failure/recovery event.

    Online routers inherit the previous converged database (a recovered node
    starts with an empty one).  Each online endpoint whose adjacency changed
    originates its historical sequence plus one and installs that LSA as its
    own entry.  Returns the updated sequence history alongside; the history
    survives a node's downtime so a recovery continues the numbering.
    """
    databases = {}
    for node in ordered_nodes:
        if node in down_nodes:
            continue
        databases[node] = {
            originator: copy_lsa(lsa)
            for originator, lsa in previous.get(node, {}).items()
        }

    next_sequences = dict(sequences)
    for node in sorted(changed):
        sequence = next_sequences.get(node, 0) + 1
        next_sequences[node] = sequence
        databases[node][node] = make_lsa(sequence, new_neighbors[node])
    return databases, next_sequences


def flood_round(previous, ordered_nodes, active_adjacency, down_nodes):
    """One synchronous flooding exchange from the previous round's databases.

    Each online router keeps its own previous database and accepts, from
    every currently available neighbor, strictly higher-sequence LSAs than
    the one it holds for that originator.  Every send reads only
    ``previous``, so no LSA travels more than one hop in a round.
    """
    current = {}
    for node in ordered_nodes:
        if node in down_nodes:
            continue
        current[node] = {
            originator: copy_lsa(lsa)
            for originator, lsa in previous[node].items()
        }
    for receiver in ordered_nodes:
        if receiver in down_nodes:
            continue
        held = current[receiver]
        for neighbor in sorted(active_adjacency[receiver]):
            for originator in sorted(previous[neighbor]):
                lsa = previous[neighbor][originator]
                known = held.get(originator)
                if known is None or lsa["sequence"] > known["sequence"]:
                    held[originator] = copy_lsa(lsa)
    return current


def _view_adjacency(database, topology):
    """Edges usable for SPF from one router's current database view.

    A declared undirected link participates only while the newest held LSAs
    of both endpoints still name each other; the topology metric is the
    single shared metric the two declarations agree on.  A one-sided stale
    LSA therefore contributes no edge.
    """
    declared = {}
    for originator, lsa in database.items():
        declared[originator] = frozenset(lsa["neighbors"])
    adjacency = {node: {} for node in declared}
    for (source, target), metric in topology.links:
        if source not in declared or target not in declared:
            continue
        if target not in declared[source] or source not in declared[target]:
            continue
        adjacency[source][target] = metric
        adjacency[target][source] = metric
    return adjacency


def public_round(round_number, databases, ordered_nodes, topology):
    """Build one public round: ``round``, sorted ``databases``, ``routers``.

    Every online router computes its forwarding table from its own database
    view alone; a down router has neither a database nor a forwarding row,
    both reported as ``null``.  All returned structures are fresh.
    """
    public_databases = {}
    routers = {}
    for node in ordered_nodes:
        if node not in databases:
            public_databases[node] = None
            routers[node] = None
            continue
        view = databases[node]
        public_databases[node] = {
            originator: copy_lsa(view[originator])
            for originator in sorted(view)
        }
        adjacency = _view_adjacency(view, topology)
        routers[node] = forwarding_table(node, ordered_nodes, adjacency)
    return {"round": round_number, "databases": public_databases, "routers": routers}


def link_state_convergence(round_zero, ordered_nodes, topology, active_adjacency, down_nodes):
    """Record round 0 and every later round in which a database changes.

    Returns ``(rounds, final_databases)`` so a replay can inherit the fixed
    point as the next event's round-zero basis.  Flooding only ever raises a
    held sequence toward a finite ceiling (one bounded counter per
    originator, exchanged inside finite components), so the scan always
    reaches a fixed point.
    """
    rounds = [public_round(0, round_zero, ordered_nodes, topology)]
    databases = round_zero
    while True:
        updated = flood_round(
            databases, ordered_nodes, active_adjacency, down_nodes
        )
        if updated == databases:
            break
        databases = updated
        rounds.append(
            public_round(len(rounds), databases, ordered_nodes, topology)
        )
    return rounds, databases

"""Regression tests for the unified replay event-progression boundary.

These tests pin the behavior that the shared timeline engine
(:mod:`packet_routing_sim.core.replay`) guarantees for every replay entry
point (``replay``, ``replay-ls`` and ``replay-dv``):

* the fault-free baseline always occupies timeline position 0 with
  ``event: null`` and no ``time``;
* empty event lists yield exactly that baseline;
* each later entry is produced by applying exactly one validated event to
  the preceding state, echoes ``time`` and the raw event verbatim (extra
  fields and the original key order included), and timeline order follows
  event order;
* consecutive node/link failures and recoveries (including a link
  explicitly disabled across a node restart, and reversed endpoint names)
  progress from inherited protocol state;
* link-state databases/sequence history and distance-vector converged
  vectors inherit *within* one call, while repeated calls start fresh and
  never share mutable results or inputs;
* outputs are independent of node/link declaration order and of the hash
  seed;
* the single error boundary is preserved: ``InvalidTopology`` /
  ``InvalidScenario`` / ``InvalidStateTransition`` for every entry point.
"""
