def oracle_holddown_stable(topology, down_nodes=frozenset(),
                           down_links=frozenset(), infinity_metric=None):
    """Stable tables of the *hold-down* round rule after every timer expires.

    The hold-down synchronous round always adopts a currently available
    direct neighbor at its direct metric (direct recovery clears a timer at
    once), and selects every other destination with the same clamp/tie
    kernel.  At a fixed point with no live timers this gives a different
    answer from plain Bellman-Ford only for a direct link that is strictly
    worse than a learned alternative: the direct route is pinned.  We derive
    the fixed point independently by iterating that one-round rule from the
    direct-only view, and assert the iteration itself terminates.
    """
    nodes, active = _adjacency(topology, down_nodes, down_links)

    def one_round(previous):
        current = {}
        for router in nodes:
            if router in down_nodes:
                current.update({(router, d): (None, None) for d in nodes})
                continue
            for dest in nodes:
                if dest == router:
                    current[router, dest] = (None, 0)
                elif dest in active[router]:
                    current[router, dest] = (
                        dest, active[router][dest]
                    )
                else:
                    best_cost, best_hop = None, None
                    for neighbor in sorted(active[router]):
                        advertised = previous[neighbor, dest][1]
                        if advertised is None:
                            continue
                        cost = active[router][neighbor] + advertised
                        if infinity_metric is not None and cost >= infinity_metric:
                            continue
                        if best_cost is None or cost < best_cost:
                            best_cost, best_hop = cost, neighbor
                    current[router, dest] = (
                        (None, None) if best_cost is None
                        else (best_hop, best_cost)
                    )
        return current

    direct = {}
    for router in nodes:
        if router in down_nodes:
            direct.update({(router, d): (None, None) for d in nodes})
            continue
        for dest in nodes:
            if dest == router:
                direct[router, dest] = (None, 0)
            elif dest in active[router]:
                direct[router, dest] = (dest, active[router][dest])
            else:
                direct[router, dest] = (None, None)
    current = direct
    for _ in range(1000):
        updated = one_round(current)
        if updated == current:
            return current
        current = updated
    raise AssertionError("hold-down oracle failed to reach a fixed point")


