import sys, random
sys.path.insert(0, "tests")
from test_distance_vector_kernel import _random_legal_case, fold_events, normalize, _adjacency

def plain_update(prev, nodes, active, down, inf):
    cur={}
    for r in nodes:
        if r in down:
            cur.update({(r,d):(None,None) for d in nodes}); continue
        for d in nodes:
            if d==r: cur[r,d]=(None,0); continue
            bc,bh=None,None
            for n in sorted(active[r]):
                am=prev[n,d][1]
                if am is None: continue
                c=active[r][n]+am
                if c>=inf: continue
                if bc is None or c<bc: bc,bh=c,n
            cur[r,d]=(None,None) if bc is None else (bh,bc)
    return cur

def fixed(prev, step):
    for _ in range(1000):
        nxt=step(prev)
        if nxt==prev: return prev
        prev=nxt
    raise AssertionError("no fixpoint")

def run_oracle(topo, events, inf, H):
    nodes, full = _adjacency(topo)
    down, dis = set(), set()
    def active():
        a={n:{} for n in nodes}
        for x in nodes:
            if x in down: continue
            for y,w in full[x].items():
                p=(x,y) if x<y else (y,x)
                if y in down or p in dis: continue
                a[x][y]=w
        return a
    def direct_view(a):
        v={}
        for r in nodes:
            if r in down:
                v.update({(r,d):(None,None) for d in nodes}); continue
            for d in nodes:
                if d==r: v[r,d]=(None,0)
                elif d in a[r]: v[r,d]=(d,a[r][d])
                else: v[r,d]=(None,None)
